report = json.loads(Path('/app/release/scanner_report.json').read_text())
out = json.loads(Path('/app/advisories.json').read_text())
assert set(out) == {'advisories'}
entries = out['advisories']
assert len(entries) == len(report['findings'])
assert [e['advisory_id'] for e in entries] == [f['advisory_id'] for f in report['findings']]
assert all(set(e) == {'advisory_id', 'verdict', 'witness', 'rejected_claim'} for e in entries)
allowed = {'APPLIES', 'NOT_LINKED', 'GC_DISCARDED', 'PATCHED_IN_PLACE', 'RUNTIME_BOUND'}
assert all(e['verdict'] in allowed for e in entries)
for e in entries:
    finding = next(f for f in report['findings'] if f['advisory_id'] == e['advisory_id'])
    assert e['rejected_claim'] == (finding['claim'] if e['verdict'] in {'NOT_LINKED', 'GC_DISCARDED', 'PATCHED_IN_PLACE'} else None)
print('validated', len(entries), 'advisories')
